class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] frequencies = new int[26];
        for (char task : tasks) {
            frequencies[task - 'A']++;
        }

        int maxFrequency = 0;
        int maxCount = 0;
        for (int frequency : frequencies) {
            if (frequency > maxFrequency) {
                maxFrequency = frequency;
                maxCount = 1;
            } else if (frequency == maxFrequency) {
                maxCount++;
            }
        }

        int frameLength = (maxFrequency - 1) * (n + 1) + maxCount;
        return Math.max(tasks.length, frameLength);
    }
}

import java.util.*;

class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] frequencies = new int[26];
        for (char task : tasks) {
            frequencies[task - 'A']++;
        }

        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int frequency : frequencies) {
            if (frequency > 0) {
                maxHeap.offer(frequency);
            }
        }

        int time = 0;
        while (!maxHeap.isEmpty()) {
            List<Integer> used = new ArrayList<>();
            int executed = 0;
            for (int slot = 0; slot <= n && !maxHeap.isEmpty(); slot++) {
                int remaining = maxHeap.poll() - 1;
                if (remaining > 0) {
                    used.add(remaining);
                }
                executed++;
            }
            for (int remaining : used) {
                maxHeap.offer(remaining);
            }
            time += maxHeap.isEmpty() ? executed : n + 1;
        }
        return time;
    }
}

