class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] frequencies = new int[26];
        for (char task : tasks) {
            frequencies[task - 'A']++;
        }

        PriorityQueue<Integer> available = new PriorityQueue<>(Collections.reverseOrder());
        for (int frequency : frequencies) {
            if (frequency > 0) {
                available.offer(frequency);
            }
        }

        Queue<int[]> cooldown = new ArrayDeque<>();
        int time = 0;
        while (!available.isEmpty() || !cooldown.isEmpty()) {
            time++;
            while (!cooldown.isEmpty() && cooldown.peek()[0] <= time) {
                available.offer(cooldown.poll()[1]);
            }
            if (!available.isEmpty()) {
                int remaining = available.poll() - 1;
                if (remaining > 0) {
                    cooldown.offer(new int[] {time + n + 1, remaining});
                }
            }
        }
        return time;
    }
}

import java.util.*;

class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] counts = new int[26];
        for (char task : tasks) {
            counts[task - 'A']++;
        }
        Arrays.sort(counts);

        int time = 0;
        while (counts[25] > 0) {
            for (int slot = 0; slot <= n; slot++) {
                if (counts[25] == 0) {
                    break;
                }
                if (slot < 26 && counts[25 - slot] > 0) {
                    counts[25 - slot]--;
                }
                time++;
            }
            Arrays.sort(counts);
        }
        return time;
    }
}
